				return
			}
			if err != nil {
				t.Fatalf("features: %v", err)
			}
			if feat == nil || !slices.Equal(feat.DisplayMode, tc.want) {
				t.Errorf("DISPLAY_MODE = %+v, want %+v", feat, tc.want)
			}
		})
	}
}

